export function getDetail(id: string): ArtFormDetail | null {
  return ART_DETAIL[id] ?? null;
}

export function hasDetail(id: string): boolean {
  return id in ART_DETAIL;
}

/** The picture the card carries. The first verified one for the form. */
export const CARD_IMAGE: Record<string, string> = Object.fromEntries(
  Object.entries(ART_DETAIL)
    .map(([id, d]) => [id, d.images[0]?.src])
    .filter(([, src]) => Boolean(src)),
) as Record<string, string>;
